using Microsoft.EntityFrameworkCore;

var options = new DbContextOptionsBuilder<School>()
    .UseSqlite("Data Source=school.db").Options;
using var db = new School(options);
Console.WriteLine(await db.Students.CountAsync());

public class Student
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
}
public class School : DbContext
{
    public School() { } // constructor dùng cho CLI trong ví dụ nhỏ
    public School(DbContextOptions<School> options) : base(options) { }
    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        if (!options.IsConfigured) options.UseSqlite("Data Source=school.db");
    }
    public DbSet<Student> Students => Set<Student>();
}

